@startuml
class FurnitureLine {
  +name : string
}

class Furniture {
  +type : string
  +reference : string
  +sellingPrice : double
}

class Component {
  +code : int
  +manufacturingPrice : double
  +type : string
}

class Store {
  +address : string
  +faxNumber : string
}

class Order {
  +orderNumber : string
  +date : date
}

class OrderLine {
  +quantity : int
}

FurnitureLine "1" *-- "1..*" Furniture : consists of
Furniture "1" *-- "1..*" Component : is composed of
Component "0..*" -- "0..*" Furniture : is used in
Store "1" -- "*" Order : places
Order "1" *-- "1..*" OrderLine : contains
OrderLine "1" --> "1" Furniture : refers to
Order "1" --> "1" Store : placed by
@enduml

